                if src[r][c] == 0:
                    empty_crosses.append((r, c))
                elif src[r][c] != 3:
                    centers.append((r, c, src[r][c]))

    def ray(r, c, dr, dc, color):
        y, x = r + dr, c + dc
        first = True
        while 0 <= y < h and 0 <= x < w:
